css:
/* Dealality Old Home — premium 6-section owner journey (v2) */
#dc-page.dc-page--premium,
.dc-page--premium {
  --bg: #0b1020;
  --bg-2: #11182a;
  --bg-3: #161e33;
  --line: rgba(255, 255, 255, 0.08);
  --text: #e8ecf5;
  --muted: rgba(232, 236, 245, 0.68);
  --soft: rgba(232, 236, 245, 0.45);
  --gold: #c4a574;
  --accent: #7c6cff;
  --max: 1080px;
  --pad: clamp(3.5rem, 7vw, 5.5rem);
  background: var(--bg);
  color: var(--text);
  font-family: "Plus Jakarta Sans", system-ui, sans-serif;
  overflow-x: hidden;
}

.dc-page--premium *,
.dc-page--premium *::before,
.dc-page--premium *::after {
  box-sizing: border-box;
}

.dc-page--premium a {
  color: inherit;
  text-decoration: none;
}

.dc-pnav {
  position: sticky;
  top: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.85rem 1.5rem;
  background: rgba(11, 16, 32, 0.88);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--line);
}

.dc-pnav-logo {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  font-weight: 650;
  letter-spacing: 0.02em;
}

.dc-pnav-logo img {
  height: 28px;
  width: auto;
  display: block;
}

.dc-pnav-links {
  display: none;
  align-items: center;
  gap: 1.35rem;
  font-size: 0.875rem;
  color: var(--muted);
}

.dc-pnav-links a:hover {
  color: var(--text);
}

.dc-pnav-right {
  display: flex;
  align-items: center;
  gap: 0.85rem;
}

.dc-pnav-signin {
  font-size: 0.875rem;
  color: var(--muted);
}

.dc-pnav-cta {
  font-size: 0.8125rem;
  font-weight: 600;
  padding: 0.55rem 0.95rem;
  border-radius: 999px;
  background: var(--text);
  color: var(--bg);
}

.dc-pnav-menu {
  display: inline-flex;
  border: 0;
  background: transparent;
  color: var(--text);
  font-size: 1.25rem;
  cursor: pointer;
  padding: 0.25rem;
}

.dc-pmnav {
  display: none;
  flex-direction: column;
  gap: 0.85rem;
  padding: 1rem 1.5rem 1.25rem;
  background: var(--bg-2);
  border-bottom: 1px solid var(--line);
}

.dc-pmnav.is-open {
  display: flex;
}

.dc-pmnav a {
  color: var(--muted);
  font-size: 0.95rem;
}

@media (min-width: 960px) {
  .dc-pnav-links {
    display: flex;
  }
  .dc-pnav-menu {
    display: none;
  }
  .dc-pmnav {
    display: none !important;
  }
}

.dc-psi {
  width: min(var(--max), calc(100% - 2.5rem));
  margin: 0 auto;
}

.dc-psec {
  padding: var(--pad) 0;
  border-top: 1px solid var(--line);
}

.dc-psec--alt {
  background: var(--bg-2);
}

.dc-pey {
  margin: 0 0 0.85rem;
  font-size: 0.72rem;
  font-weight: 650;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--gold);
}

.dc-ph1 {
  margin: 0;
  max-width: 14ch;
  font-size: clamp(2rem, 4.4vw, 3.15rem);
  line-height: 1.08;
  letter-spacing: -0.03em;
  font-weight: 600;
}

.dc-ph2 {
  margin: 0;
  max-width: 22ch;
  font-size: clamp(1.55rem, 2.8vw, 2.15rem);
  line-height: 1.15;
  letter-spacing: -0.025em;
  font-weight: 600;
}

.dc-plead {
  margin: 1rem 0 0;
  max-width: 42rem;
  font-size: 1.05rem;
  line-height: 1.55;
  color: var(--muted);
}

.dc-pctas {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1.75rem;
}

.dc-pbtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.75rem;
  padding: 0.7rem 1.2rem;
  border-radius: 999px;
  font-size: 0.9rem;
  font-weight: 600;
  background: var(--text);
  color: var(--bg);
}

.dc-pbtn--ghost {
  background: transparent;
  color: var(--text);
  border: 1px solid var(--line);
}

.dc-phero {
  padding: clamp(3.25rem, 8vw, 5.5rem) 0 var(--pad);
  border-top: 0;
}

.dc-phero-grid {
  display: grid;
  gap: 2.5rem;
}

@media (min-width: 960px) {
  .dc-phero-grid {
    grid-template-columns: 1.05fr 0.95fr;
    align-items: center;
    gap: 3rem;
  }
}

.dc-pvisual {
  border: 1px solid var(--line);
  border-radius: 1.1rem;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.03), transparent 40%),
    var(--bg-3);
  padding: 1.25rem;
}

.dc-pvisual-label {
  margin: 0 0 1rem;
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--soft);
}

.dc-pflow {
  display: grid;
  gap: 0.65rem;
}

.dc-pflow-step {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.85rem;
  align-items: start;
  padding: 0.85rem 0.95rem;
  border-radius: 0.8rem;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid transparent;
}

.dc-pflow-step.is-accent {
  border-color: rgba(196, 165, 116, 0.35);
  background: rgba(196, 165, 116, 0.06);
}

.dc-pflow-n {
  width: 1.5rem;
  height: 1.5rem;
  border-radius: 999px;
  display: grid;
  place-items: center;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--bg);
  background: var(--gold);
}

.dc-pflow-step:not(.is-accent) .dc-pflow-n {
  background: rgba(255, 255, 255, 0.16);
  color: var(--text);
}

.dc-pflow-t {
  margin: 0;
  font-size: 0.95rem;
  font-weight: 600;
}

.dc-pflow-d {
  margin: 0.2rem 0 0;
  font-size: 0.84rem;
  line-height: 1.45;
  color: var(--soft);
}

.dc-plist {
  list-style: none;
  margin: 1.75rem 0 0;
  padding: 0;
  border-top: 1px solid var(--line);
}

.dc-plist li {
  padding: 1rem 0;
  border-bottom: 1px solid var(--line);
  font-size: 1.05rem;
  line-height: 1.4;
  color: var(--text);
}

.dc-pjourney {
  display: grid;
  gap: 0;
  margin-top: 2rem;
  border: 1px solid var(--line);
  border-radius: 1rem;
  overflow: hidden;
}

.dc-pjourney-item {
  display: grid;
  grid-template-columns: 2.5rem 1fr;
  gap: 0.85rem;
  padding: 1.1rem 1.15rem;
  border-top: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.015);
}

.dc-pjourney-item:first-child {
  border-top: 0;
}

.dc-pjourney-n {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--gold);
  padding-top: 0.15rem;
}

.dc-pjourney-t {
  margin: 0;
  font-size: 1rem;
  font-weight: 600;
}

.dc-pproof {
  display: grid;
  gap: 1rem;
  margin-top: 2rem;
}

@media (min-width: 800px) {
  .dc-pproof {
    grid-template-columns: repeat(3, 1fr);
  }
}

.dc-pproof article {
  padding: 1.2rem 1.15rem 1.3rem;
  border: 1px solid var(--line);
  border-radius: 0.95rem;
  background: rgba(255, 255, 255, 0.02);
}

.dc-pproof h3 {
  margin: 0;
  font-size: 1rem;
  font-weight: 650;
  line-height: 1.35;
}

.dc-pproof p {
  margin: 0.65rem 0 0;
  font-size: 0.92rem;
  line-height: 1.5;
  color: var(--muted);
}

.dc-ptrust {
  display: grid;
  gap: 1.5rem;
  margin-top: 1.75rem;
}

@media (min-width: 860px) {
  .dc-ptrust {
    grid-template-columns: 1.2fr 0.8fr;
    align-items: end;
  }
}

.dc-ptrust-points {
  display: grid;
  gap: 0.9rem;
}

.dc-ptrust-points p {
  margin: 0;
  padding-left: 0.95rem;
  border-left: 2px solid rgba(196, 165, 116, 0.45);
  font-size: 0.95rem;
  line-height: 1.5;
  color: var(--muted);
}

.dc-ptrust-points strong {
  display: block;
  color: var(--text);
  font-weight: 650;
  margin-bottom: 0.15rem;
}

.dc-pcred {
  padding: 1.15rem 1.2rem;
  border-radius: 0.95rem;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.03);
}

.dc-pcred p {
  margin: 0;
  font-size: 0.92rem;
  line-height: 1.5;
  color: var(--muted);
}

.dc-pcred .dc-pby {
  margin-top: 0.85rem;
  color: var(--text);
  font-weight: 600;
}

.dc-pcta {
  text-align: left;
}

.dc-pfoot {
  border-top: 1px solid var(--line);
  background: #080c18;
  padding: 2.75rem 0 2rem;
}

.dc-pfoot-grid {
  display: grid;
  gap: 1.75rem;
}

@media (min-width: 800px) {
  .dc-pfoot-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
  }
}

.dc-pfoot h3 {
  margin: 0 0 0.85rem;
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--soft);
  font-weight: 650;
}

.dc-pfoot a {
  display: block;
  margin: 0.45rem 0;
  font-size: 0.92rem;
  color: var(--muted);
}

.dc-pfoot a:hover {
  color: var(--text);
}

.dc-pfoot-copy {
  margin: 2rem 0 0;
  padding-top: 1.25rem;
  border-top: 1px solid var(--line);
  font-size: 0.8rem;
  color: var(--soft);
}
